S2("gen",{"qinshihuang": {"meet": ["朕乃大秦始皇帝嬴政！天運者，你這座燈塔雖小，卻有統一天下之象——朕便暫借你這方星盤，再平一次四海！"], "tideWin": "普天之下，莫非王土！敵軍已盡數伏誅！", "tideLose": "哼，一時失利罷了！重整大秦銳士，十倍奉還！"}, "liubang": {"meet": ["哈哈哈哈！赤帝子劉季來也！兄弟，看你這座城甚有意思，可缺個能為你安撫這群傲氣傑才的老大哥？"], "tideWin": "哈哈哈哈！看見沒，最後贏的還是咱們大漢！", "tideLose": "留得青山在不怕沒柴燒！兄弟快撤，回頭再找他們算帳！"}, "hanwudi": {"meet": ["朕乃大漢孝武皇帝劉徹！這歸墟黑霧竟敢肆虐華夏山河？好，給朕三千鐵騎，朕帶你一路殺到荒原盡頭！"], "tideWin": "哈哈哈哈！犯我強漢者，這便是下場！", "tideLose": "一時挫折算什麼？重整羽林鐵騎，必踏平敵營！"}, "caocao": {"meet": ["哈哈哈哈！治世之能臣，亂世之奸雄——曹孟德來也！主公，你這座城裡群雄雲集，正合孤的胃口！"], "tideWin": "哈哈哈哈！區區敵寇，豈是虎豹騎對手！", "tideLose": "勝敗乃兵家常事！當年赤壁大敗孤都挺過來了，走，整軍再戰！"}, "tangtaizong": {"meet": ["秦王李世民，見過天運者！這片歸墟雖被黑霧籠罩，卻仍有萬千蒼生待救——玄甲軍已就位，請君下令！"], "tideWin": "玄甲所至，萬敵披靡！善待降卒，不可妄殺！", "tideLose": "一時受挫無妨，玄甲軍結陣緩撤，絕不潰散！"}, "wuzetian": {"meet": ["朕乃大周聖神皇帝武曌！天運者，你竟敢將千古女皇召至麾下？好氣魄——讓本宮看看，你配不配與我共坐這張龍椅！"], "tideWin": "日月所照，逆我者亡！全軍凱旋！", "tideLose": "一時失算罷了！記住這筆帳，本宮必十倍討還！"}, "zhaokuangyin": {"meet": ["大宋太祖趙匡胤，見過主公！這歸墟亂世像極了五代十國，咱們一起把它理出個太平秩序來！"], "tideWin": "收兵！善待百姓，不可縱兵劫掠！", "tideLose": "穩住陣腳，殿前禁軍斷後，絕不可自亂！"}, "zhuyuanzhang": {"meet": ["咱乃大明太祖高皇帝朱元璋！天運者，你這座城牆還不夠厚、糧倉還不夠滿——讓咱來替你好好管管！"], "tideWin": "驅除黑霧，恢復中華！哈哈哈哈！", "tideLose": "退回城裡高牆死守！只要咱們糧多牆厚，早晚耗死他們！"}, "mulan": {"meet": ["北魏花木蘭報到！莫問兒女事，只管予我一匹快馬、一桿長槍！"], "tideWin": "敵陣已潰！弟兄們隨我追擊十里，莫放走一個！", "tideLose": "一時大意……主公先撤，我來斷後！"}, "change": {"meet": ["月輪西沉、星盤初明……妾身嫦娥，自廣寒清境而來，願以月華為君驅散黑霧。"], "tideWin": "月華所照，邪祟自散。", "tideLose": "陰雲蔽月……夫君速退，妾身以月華斷後。"}, "xiaoqiao": {"meet": ["江東小喬見過主公。前塵煙雨已散，這座星盤燈塔，便是妾身新的歸處麼？"], "tideWin": "太好了！江東兒女亦不輸於天下英雄！", "tideLose": "對不起主公……小喬沒能守住陣腳……"}, "zhenmi": {"meet": ["彷彿若輕雲蔽月，飄颻若流風迴雪……妾身甄宓，見過天運者。願此地不再有薄情帝王之悲。"], "tideWin": "輕雲蔽月，流風迴雪——敵軍已潰！", "tideLose": "一時失算……請主公速速撤離！"}});
