S2("cq",{"qinshihuang": {"tun": "耕戰立國，屯田為先！", "qing": "適度休養即可，不可廢弛法度。", "qiang": "強兵掃六合，正合朕意！", "kuang": "開山鑿石築長城，刻不容緩！", "ji": "封禪泰山之威重現星盤，甚善！", "shou": "高牆鐵壁，萬世不破！"}, "liubang": {"tun": "讓老百姓有飯吃，天下就穩了一半！", "qing": "約法三章、減免賦稅，我舉雙手雙腳贊成！", "qiang": "重賞之下必有勇夫，練兵別心疼錢！", "kuang": "多採木石蓋大城，氣派！", "ji": "祭天拜星盤，把咱們的天命氣勢造起來！", "shou": "先把家門守牢，外面打輸了也有地方退！"}, "hanwudi": {"tun": "兵馬未動糧草先行，囤足軍糧好遠征！", "qing": "偶爾與民休息亦是為了下次更猛的出擊。", "qiang": "強兵！大漢雄風全靠鐵血精兵！", "kuang": "多採精鐵良木鑄造環首刀與重甲！", "ji": "祭天泰山、星盤賜福，必能旗開得勝！", "shou": "修好邊塞堡壘，作為我軍前出進攻的跳板！"}, "caocao": {"tun": "孤當年靠屯田稱霸北方，此令必行！", "qing": "亂世收攏人心，減賦甚妥。", "qiang": "強兵！亂世唯有拳頭硬才能說話！", "kuang": "採木採石造衝車與銅雀臺，甚好！", "ji": "藉星盤天命號令天下，妙極！", "shou": "固守本營方能伺機破敵。"}, "tangtaizong": {"tun": "農為國本，屯田積糧最為穩妥。", "qing": "貞觀之治首重輕徭薄賦、與民休息！", "qiang": "居安思危，玄甲精兵不可一日懈怠！", "kuang": "取木石以固城池、興民居，甚善。", "ji": "敬天法祖、淨化黑霧，可安天下之心。", "shou": "固本培元，城池方能立於不敗之地。"}, "wuzetian": {"tun": "勸課農桑乃大周國策，屯田必行！", "qing": "讓百姓富足，方能支撐盛世氣象。", "qiang": "強兵足以震懾四夷，本宮贊成。", "kuang": "採木石建明堂與高牆，彰顯皇威！", "ji": "日月當空、祭告星盤，天命必歸我等！", "shou": "固守中樞，萬無一失。"}, "zhaokuangyin": {"tun": "民以食為天，屯田積糧最為根本。", "qing": "仁政愛民，城池自然興旺！", "qiang": "練兵須重紀律，仁義之師方能無敵。", "kuang": "採木石修民居與市集，造福百姓。", "ji": "祭天安民，順應星盤天命。", "shou": "穩守根基方能徐圖大業，我力薦堅壁令！"}, "zhuyuanzhang": {"tun": "廣積糧！屯田令就是咱最愛的政令！", "qing": "減免農稅、讓百姓休養生息，咱舉雙手贊成！", "qiang": "兵馬既能打仗又能屯田，甚好！", "kuang": "多採青石好木頭，把城牆修得比山還厚！", "ji": "祭告天地星盤，祈求風調雨順大豐收！", "shou": "高築牆！堅壁令必須立刻執行！"}, "mulan": {"tun": "兵馬未動糧草先行，屯田甚妥！", "qing": "百姓安居樂業，前線弟兄方能無後顧之憂！", "qiang": "下強兵令，將新兵全練成百戰精銳！", "kuang": "多採精石良木修繕兵器與馬廄！", "ji": "點亮星盤驅散黑霧，弟兄們夜戰便多三分勝算！", "shou": "高牆深溝護我城中老小，木蘭附議！"}, "change": {"tun": "衣食足則人心安。", "qing": "寬仁待民，如春風化雨。", "qiang": "止戈為武，有備無患。", "kuang": "取之有度，以固城防。", "ji": "日月星辰共鳴，正是驅霧良機。", "shou": "護住這方人間淨土，甚妥。"}, "xiaoqiao": {"tun": "倉廩豐足，百姓方能安穩度日。", "qing": "減輕商稅賦役，市集立時便能繁華起來！", "qiang": "有強兵護持，商隊方敢放心往來。", "kuang": "多採木石，把城池修得如江南水鄉般雅緻！", "ji": "祈求星盤護佑風調雨順、合家安康。", "shou": "把城牆砌得牢靠些，大家夜裡睡得才踏實。"}, "zhenmi": {"tun": "倉廩實方能安民，屯田為要。", "qing": "仁政養民，國本自固。", "qiang": "外患未平，精兵不可廢。", "kuang": "備足木石建材，城池方能日益興盛。", "ji": "共鳴星盤、驅散黑霧，甚為妥當。", "shou": "高築城牆以防不測，妾身附議。"}});
S2("wander",{"qinshihuang": "黑霧漫天又如何？朕乃始皇帝，這片歸墟，該迎來真正的主人了！", "liubang": "哈哈，這荒原總算有個像樣的落腳處啦！漢高祖劉邦在此，兄弟，缺不缺個幫手？", "hanwudi": "大漢孝武皇帝劉徹在此！天運者，可敢與朕一同踏破這無邊黑霧？", "caocao": "哈哈哈哈！曹孟德在此！這片歸墟亂世，正缺孤這樣一位亂世梟雄！", "tangtaizong": "大唐秦王李世民在此！既見明主與星盤清輝，願共開歸墟盛世！", "wuzetian": "日月當空，星盤相召！武曌在此，天運者，準備好迎接真正的盛世了嗎？", "zhaokuangyin": "大宋趙匡胤在此！願隨主公止戈息兵、重塑太平人間！", "zhuyuanzhang": "哈哈，這荒原總算有座像樣的城池了！朱元璋在此，咱替你把牆築高、把糧囤滿！", "mulan": "總算看見星盤燈塔的光了！花木蘭在此，這座城還缺一桿衝鋒的長槍嗎？", "change": "循著星盤清輝而來，願與君共守這片不再孤寂的人間。", "xiaoqiao": "總算走出這片森寒黑霧了……江東小喬拜見主公，懇請收留。", "zhenmi": "洛水煙波已遠，幸見星盤明燈。甄宓願隨主公，共築一座再無背叛的新城。"});
S2("wed",{"qinshihuang": {"n": ["天運者來了？正好，看看朕剛擬好的《歸墟統一法度》。", "深夜來訪，可是前線戰局有變？坐下說。", "關中老酒溫好了，這世上唯有你配與朕對飲。", "別拘禮了，在朕這兒，咱們是共平天下的霸主盟友。"], "talk": ["當年朕十三歲登基，親政後掃平嫪毐、罷黜呂不韋，靠的從不是仁慈，而是絕對的決斷。", "世人罵朕暴虐，卻忘了沒有大秦一統，華夏還要再打幾百年戰國亂世。", "你比朕多了一份溫厚，這倒讓許多連朕都收服不了的清流賢才死心塌地跟著你。", "這歸墟裡集結了歷代豪傑，真是千古未有的大舞台！", "朕不求你封朕為王，只求你別重演大秦二世而亡的悲劇。", "咱們兄弟聯手，把這片破碎山河重新鑄成鐵桶一塊！"], "ev": [{"k": "v0", "at": 1, "t": "統一度量", "l": [["n", "秦始皇親自校準全城糧斗與建材尺碼，杜絕商販偷斤減兩，國庫大增"]], "eff": {"food": 40, "wood": 25, "aff": ["me", 8]}}, {"k": "v1", "at": 3, "t": "修築歸墟長城", "l": [["n", "秦始皇親自督工以夯土青石加固城防，燈塔固若金湯"]], "eff": {"stone": -15, "dur": 20, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "玄黑對飲", "l": [["n", "深夜城頭，始皇帝難得放下威嚴與你舉杯暢談萬世基業"]], "eff": {"talent": 1, "aff": ["me", 10]}}], "duty": {"van": "大秦弩車開道，碾碎一切頑抗之敵！", "guard": "朕坐鎮中樞，法度森嚴，城池永固！", "strat": "統一大業須從長計議，依朕之策必成！"}, "cold": "好幾旬不見你來議政，莫非沉溺溫柔鄉忘了統一大業？", "colds": ["好幾旬不見你來議政，莫非沉溺溫柔鄉忘了統一大業？", "竹簡都堆成山了，快過來與朕共商國是！"]}, "liubang": {"n": ["兄弟來了？快快解履上榻，酒肉皆已備妥！", "剛自市肆而歸，聞得滿腹百姓趣事，快坐下聽乃公細細道來！", "莫要擺出主公架子，入得此室，我等僅為沛縣老兄弟！", "來得正好，隨乃公品鑑此壇新釀的關中美酒！"], "talk": ["當年鴻門宴上，項莊舞劍差點令乃公驚出一身冷汗，幸蒙子房與樊噲相救。為人者，關鍵時刻當知伸屈之道！", "實則我心深敬蕭何，若無他在關中傾力送糧，我早為項羽所破。", "兄弟你對待女眷比我厚道多了，不像我當年惹得呂雉怨恨一輩子。", "這歸墟裡皇帝、名將扎堆，能把這幫人捏成一團，兄弟你真有兩把刷子！", "等咱們把黑霧全清空，建一座比長安還大的酒館，咱倆喝他個三天三夜！", "好兄弟，有乃公在，無人敢在背後暗算於你！"], "ev": [{"k": "v0", "at": 1, "t": "約法安民", "l": [["n", "劉邦親自去流民坊和百姓蹲在地上吃餅聊天，三言兩語便平息了流民恐慌"]], "eff": {"pop": 35, "affAll": 4, "aff": ["me", 8]}}, {"k": "v1", "at": 3, "t": "酒桌收心", "l": [["n", "劉邦做東請幾位鬧矛盾的武將喝酒吹牛，一頓酒下來眾將勾肩搭背冰釋前嫌"]], "eff": {"food": -15, "train": 10, "affAll": 5, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "大風夜唱", "l": [["n", "月下微醺，劉邦擊筑高歌《大風歌》，激盪起全城豪情"]], "eff": {"energy": 25, "aff": ["me", 10]}}], "duty": {"van": "命乃公為先鋒？甚好，我率眾直衝，若勢不可為便帶弟兄們權宜退兵！", "guard": "坐鎮城池收聚人心？此乃乃公絕技！", "strat": "論及知人善任、分化敵勢，聽乃公之言定無差錯！"}, "cold": "數旬未見你來與乃公共飲暢談，兄弟位至尊位便不認老哥了？", "colds": ["數旬未見你來與乃公共飲暢談，兄弟位至尊位便不認老哥了？", "酒都溫涼三回了，快過來坐坐嘛！"]}, "hanwudi": {"n": ["兄弟來了？快觀此沙盤，北面那塊要地我等明日便將其拿下！", "剛與去病比完騎射，正覺痛快，進來喝一碗！", "這歸墟長夜漫漫，唯有與你論天下大勢最解悶。", "酒已溫滾燙，今夜咱們只談開疆拓土，不談瑣事！"], "talk": ["朕十六歲登基，受夠了太皇太后和保守老臣的掣肘，憋著一口氣才打出河西走廊。", "去病二十四歲便走了，那是朕一輩子最大的痛。在這座城裡看他生龍活虎，朕心裡那塊缺口總算補上了。", "說起來，朕晚年犯過巫蠱之禍的糊塗錯，幸好兄弟你頭腦清醒，絕不會步我後塵。", "男兒生於亂世，就該提三尺劍立不世之功！", "有你這位知機識度的兄弟替我把控進退，我等聯手天下無雙！", "待奪回沉沒長安那日，咱們兄弟一起登未央宮舊址痛飲！"], "ev": [{"k": "v0", "at": 1, "t": "羽林閱兵", "l": [["n", "漢武帝親自檢閱騎兵演練衝鋒，全軍氣勢如虹"]], "eff": {"train": 15, "atkNext": 0.12, "aff": ["me", 8]}}, {"k": "v1", "at": 3, "t": "鹽鐵籌資", "l": [["n", "漢武帝獻上鹽鐵官營之策，短期內大幅充實國庫糧財"]], "eff": {"food": 45, "energy": 20, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "輪台夜省", "l": [["n", "深夜裡漢武帝難得放下雄主驕傲，與你坦誠談起昔年過失與治國心得"]], "eff": {"talent": 1, "aff": ["me", 10]}}], "duty": {"van": "羽林鐵騎隨朕衝鋒，踏平一切阻礙！", "guard": "朕坐鎮城中，誰敢來犯必遭十倍反擊！", "strat": "攻敵必救、斷其糧道，依朕之策必大破敵軍！"}, "cold": "好幾旬沒來找朕商議北伐大計了，兄弟你該不會想當守成之君了吧？", "colds": ["好幾旬沒來找朕商議北伐大計了，兄弟你該不會想當守成之君了吧？", "羽林軍之戰馬皆快怠惰生贅肉了，快來共飲調兵！"]}, "caocao": {"n": ["兄弟來了？快坐，孤剛註完半卷《孫子兵法》，正缺個懂行的人評點！", "對酒當歌，今夜無戰事，咱們兄弟一醉方休！", "剛與華佗喝完藥茶，頭風全好了，快來陪孤下盤棋！", "外頭霧冷，進來烤火！孤有幾條分化四大敵對勢力的毒計想跟你聊聊。"], "talk": ["當年討董卓時，十八路諸侯個個懷鬼胎，唯獨孤真敢提兵追殺。這世道，靠別人不如靠自己！", "其實孤一輩子沒稱帝，不是不敢，是覺得名分虛無，實權在手、平定亂世才最要緊。", "你把孫武、韓信、白起全聚在一處，這陣容連孤看了都眼紅！", "莫要總戒備孤存反意——這歸墟之中唯有你這座城池最富興味，孤尚未盡興呢！", "若是哪天咱們打下沉沒長安，孤一定要在城頭大唱一曲《龜雖壽》！", "兄弟，世上知孤者甚少，你乃唯一知己！"], "ev": [{"k": "v0", "at": 1, "t": "曹魏屯田法", "l": [["n", "曹操將軍屯與民屯結合推廣至全城荒地，糧食收成大漲"]], "eff": {"food": 45, "aff": ["me", 8]}}, {"k": "v1", "at": 3, "t": "青梅煮酒", "l": [["n", "微雨午後，曹操備下青梅與溫酒與你論天下英雄，暢快淋漓"]], "eff": {"talent": 1, "aff": ["me", 10]}}, {"k": "v2", "at": 6, "t": "虎豹夜演", "l": [["n", "曹操親率虎豹騎演練夜間穿插突擊，全軍戰意高漲"]], "eff": {"train": 12, "atkNext": 0.12, "aff": ["me", 8]}}], "duty": {"van": "虎豹騎聽令，隨孤踏平前線！", "guard": "孤坐鎮中樞，內修屯田、外防宵小，萬無一失！", "strat": "兵者詭道，孤這套連環奇策，定教敵軍摸不著頭腦！"}, "cold": "好幾旬沒來陪孤煮酒論英雄了，兄弟該不會在防著孤吧？", "colds": ["好幾旬沒來陪孤煮酒論英雄了，兄弟該不會在防著孤吧？", "酒溫了又涼，快過來聊聊，別讓孤悶出頭風來！"]}, "tangtaizong": {"n": ["兄長來了？快請入座，剛泡好長安清茶，正好共論治國之道。", "今日玄甲軍操練甚佳，來喝兩杯西域葡萄酒慶賀一下吧！", "見兄長眉頭微皺，可是朝堂派系又起爭執了？說來聽聽。", "難得清閒之夜，咱們兄弟不談軍務，只臨帖論書法如何？"], "talk": ["我十八歲便隨父起兵，二十餘歲便幾乎打遍天下無敵手，深知打天下靠銳氣，守天下靠仁心。", "當年魏徵天天在朝堂上指著我鼻子罵，我氣得想殺他，卻還是忍下來改錯——因為我知道他是真心為江山好。", "看著歸墟裡歷代英靈齊聚，秦皇漢武皆在此處，真是壯哉！", "兄長待下寬厚而不失果決，這份胸襟連世民都自愧不如。", "若他日奪回長安，世民願親率玄甲軍為兄長開道入城！", "兄弟同心，其利斷金。這片新世界，必將迎來屬於咱們的貞觀之治！"], "ev": [{"k": "v0", "at": 1, "t": "玄甲破霧演武", "l": [["n", "唐太宗親率玄甲騎兵演練楔形衝鋒，全軍士氣大振"]], "eff": {"train": 12, "atkNext": 0.12, "aff": ["me", 8]}}, {"k": "v1", "at": 3, "t": "貞觀納諫", "l": [["n", "唐太宗當眾向你直言指出城中三處內政積弊，你從諫如流大獲民心"]], "eff": {"pop": 25, "talent": 1, "aff": ["me", 10]}}, {"k": "v2", "at": 6, "t": "蘭亭夜話", "l": [["n", "深夜燈下，唐太宗與你共賞書法、暢飲西域美酒"]], "eff": {"aff": ["me", 10], "affAll": 2}}], "duty": {"van": "玄甲軍隨我衝鋒，破開黑霧！", "guard": "有世民坐鎮，定保城池政通人和、固若金湯！", "strat": "兼聽則明，世民已為兄長備妥萬全破敵之策！"}, "cold": "兄長許久未曾來與世民對弈論政了，莫非嫌我太愛直諫？", "colds": ["兄長許久未曾來與世民對弈論政了，莫非嫌我太愛直諫？", "西域新至的美酒已陳放多時，快來共飲一杯吧！"]}, "wuzetian": {"n": ["夫君來得正好，本宮剛替你擬完明天的朝會方略。把門關上，今晚該談咱們夫妻的私事了。", "卸下千古女皇的冠冕，頸子倒真有些痠。過來，替本宮揉揉肩。", "外頭霧氣冷得很，快進來喝杯洛陽牡丹釀，暖暖身子再說話。", "這滿城英雄皆俯首於你，唯獨在這裡，夫君得聽本宮的。"], "talk": ["十四歲入宮為才人、感業寺削髮為尼、再一步步爬上大周女皇之位——這條路，每一步都是踏著刀鋒走過來的。", "所以我從不信什麼溫情脈脈的空話，唯獨夫君你，讓本宮願意放下幾分戒心。", "呂雉與我頗為相似，只是她甘願止步於太后，而我，天生就該站在最高處。", "莫怕本宮野心勃勃會奪你帝位——只要你永比本宮更為強大英明，本宮便心甘情願與你二聖共治。", "牡丹花開時最是國色天香，等咱們平定歸墟，在長安種滿洛陽牡丹吧。", "能與你旗鼓相當地交鋒、又在深夜相擁而眠，這才是帝王該有的伴侶。"], "ev": [{"k": "v0", "at": 1, "t": "二聖臨朝", "l": [["n", "武則天親自替你審閱並改良了全城官制考核，大幅提升行政效率"]], "eff": {"talent": 2, "food": 30, "aff": ["me", 10]}}, {"k": "v1", "at": 3, "t": "鐵鞭馴馬", "l": [["n", "校場一匹狂躁的荒原烈馬無人敢騎，武則天冷笑著親自以鐵鞭馴服，震懾全營"]], "eff": {"train": 12, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "牡丹紅燭", "l": [["n", "深夜暖閣，武則天換下龍袍披上大紅牡丹紗衣，罕見地展現傾城柔情"]], "eff": {"aff": ["me", 12]}}], "duty": {"feed": "後宮與內廷交由本宮，保證如大周宮闕般森嚴有序、滴水不漏。", "war": "論調兵遣將與權衡諸將，本宮從未輸過任何男帝。", "rite": "日月當空，本宮親自主持星盤大祭，天命自歸我等！"}, "cold": "夫君已有數旬未踏進本宮寢殿……怎麼，怕本宮的氣勢壓過你，躲去別的溫柔鄉了？", "colds": ["夫君已有數旬未踏進本宮寢殿……怎麼，怕本宮的氣勢壓過你，躲去別的溫柔鄉了？", "奏章批完了，牡丹釀也溫好了，夫君連見本宮一面的膽量都沒有嗎？"]}, "zhaokuangyin": {"n": ["兄弟來了？快坐，溫了壺汴京清酒，咱們邊喝邊聊！", "剛在城裡逛了一圈，市集繁榮得很，快進來聽聽好消息！", "別忙了，先歇口氣，陪老趙下盤棋解解乏。", "今夜風靜，正好與兄弟聊聊如何穩固朝堂平衡。"], "talk": ["五代五十多年換了五個朝代，天天兵變殺人，我當上皇帝後發誓絕不讓大宋再走老路。", "雖然後世說我重文抑武太過，可在當時，那真是為了保住天下百姓不再受兵禍啊。", "在這裡看見岳飛被救下來，我心裡這塊大石頭總算落了地。", "兄弟你既有武勇又有仁心，比我那幾個後代子孫強上一萬倍！", "咱們兄弟喝這杯酒，不釋兵權，只求同心共濟！", "往後無論內政外戰，老趙永遠站在兄弟身後！"], "ev": [{"k": "v0", "at": 1, "t": "太祖長拳授藝", "l": [["n", "趙匡胤親赴校場傳授太祖長拳，大幅提升全軍步兵體魄"]], "eff": {"train": 12, "sol": 20, "aff": ["me", 8]}}, {"k": "v1", "at": 3, "t": "汴京夜市", "l": [["n", "趙匡胤借鑑北宋夜市之法取消宵禁，市集稅收與流民大增"]], "eff": {"food": 35, "pop": 20, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "雪夜訪趙普", "l": [["n", "雪夜裡趙匡胤與你圍爐烤肉飲酒，共定「先易後難」的歸墟擴張方略"]], "eff": {"talent": 1, "aff": ["me", 10]}}], "duty": {"van": "蟠龍棍出鞘，老趙替兄弟打穿前陣！", "guard": "有趙某坐鎮，城池內外必保井然有序！", "strat": "先易後難、文武相濟，依我此策必能穩步稱霸！"}, "cold": "好幾旬沒來陪老趙喝杯清酒了，兄弟最近很忙啊？", "colds": ["好幾旬沒來陪老趙喝杯清酒了，兄弟最近很忙啊？", "烤肉都涼了，快過來聊聊朝政與家常嘛！"]}, "zhuyuanzhang": {"n": ["兄弟來了？快坐，咱剛熬好一鍋熱騰騰的雜糧蔬菜湯，來喝一碗！", "剛把各倉的庫存全核對了一遍，一粒米都沒少，痛快！", "別板著臉了，坐下跟咱老朱聊聊怎麼把這座城修得更結實！", "外頭霧大，快進屋烤火，咱這兒有剛烤好的燒餅！"], "talk": ["當年淮西大旱，爹娘和大哥全餓死了，連塊埋人的地都沒有。所以咱發誓，這輩子絕不讓治下百姓再挨餓！", "咱知道自己脾氣暴、下手狠，可對付那些吸百姓血的貪官，心軟就是對窮苦人殘忍！", "你這座城裡收留了這麼多不同朝代的流民，能讓他們吃飽穿暖，功德無量！", "沈萬三這人雖好炫耀，築城倒是勤力，咱日後少責罰他幾句便是。", "兄弟，只要咱們把牆築得最高、糧囤得最厚，四大勢力全得被咱們活活耗垮！", "有咱老朱在，你的後方永遠鐵板一塊！"], "ev": [{"k": "v0", "at": 1, "t": "洪武魚鱗冊", "l": [["n", "朱元璋親自編纂全城田畝與流民魚鱗圖冊，杜絕逃稅與隱匿，糧產大增"]], "eff": {"food": 50, "aff": ["me", 8]}}, {"k": "v1", "at": 3, "t": "糯米築堅城", "l": [["n", "朱元璋督造工匠以糯米漿與巨石加固城牆，燈塔防禦大增"]], "eff": {"stone": -15, "dur": 20, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "粗茶淡飯夜談", "l": [["n", "朱元璋親手做了一桌家常粗茶淡飯與你共食，暢談開國艱辛"]], "eff": {"aff": ["me", 10], "affAll": 2}}], "duty": {"van": "咱當年也是從千軍萬馬裡殺出來的，打前鋒絕不含糊！", "guard": "高築牆、廣積糧！咱坐鎮中樞，城池萬無一失！", "strat": "緩稱王、蓄實力，聽咱老朱的穩紮穩打策略準贏！"}, "cold": "好幾旬沒來陪咱喝雜糧湯了，兄弟該不會吃慣山珍海味嫌咱這兒寒酸了吧？", "colds": ["好幾旬沒來陪咱喝雜糧湯了，兄弟該不會吃慣山珍海味嫌咱這兒寒酸了吧？", "帳本和城防圖都畫好了，快過來看看嘛！"]}, "mulan": {"n": ["兄弟來了？快坐，我剛替戰馬刷完鬃毛，順手溫了壺北境烈酒。", "更深露重還來軍營巡視，又是睡不著了？來，同我看看明日行軍輿圖。", "早料到你這時辰會來！炭火上的炙餅還熱乎著，快拿一塊。", "今夜星輝清朗，莫悶在帳裡了，上城頭吹風對飲去！"], "talk": ["當年阿爺年邁、阿弟尚幼，我剪斷長髮披上舊甲時，指節其實也在抖。可跨上馬鞍那一刻，我便知此去絕無回頭路。", "同行十二載，那些老袍澤直到凱旋見我換上女裝，個個驚得說不出話來，如今回想仍覺好笑。", "這歸墟裡處處是權謀算計，唯獨跟著兄弟你，教我覺得提槍流血是有歸處的。", "莫擔心我衝陣太拚命。昔日是為了活著回家，如今是為了與兄弟親眼看見黑霧散盡。", "營裡白起、霍去病皆是千古名將，能與他們同袍切磋，我這套槍法又精進不少。", "待天下太平那日，我定要回織布機前安安靜靜織一匹最細密的錦緞贈予兄弟。"], "ev": [{"k": "v0", "at": 1, "t": "北境夜訓", "l": [["n", "深夜校場寒風刺骨，花木蘭正領著一隊新兵在微弱火把下練習聽聲辨位。"], ["p", "木蘭，都過二更了，怎還在帶隊夜訓？"], ["mulan", "黑霧潮專挑深夜襲城，弟兄們若只慣於白日對陣，夜裡必吃大虧。"], ["p", "你這份練兵的細心與韌勁，全軍罕有其匹。"], ["mulan", "（抹去額角細汗，爽朗一笑）「兄弟過譽了！來，替我瞧瞧這套夜襲變陣可還有破綻！"]], "eff": {"train": 12, "aff": ["me", 8]}}, {"k": "v1", "at": 3, "t": "重修舊機杼", "l": [["n", "難得休沐，你在流民坊撞見花木蘭正蹲在廊下，替一名白髮老嫗修補斷線的木織機，手法熟練得令人驚訝。"], ["p", "未料叱吒沙場的花將軍，修起織機亦是一把好手。"], ["mulan", "（拍去掌心棉絮，眼底柔和）「『唧唧復唧唧，木蘭當戶織』嘛。咱們在外頭拚死打仗，為的不就是教城裡的織布機永遠不停麼？"], ["p", "說得好。今晚全坊加餐，記你頭功！"]], "eff": {"pop": 20, "food": 20, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "明駝千里酒", "l": [["n", "城頭月色如霜，花木蘭遞來兩碗北魏燒酒，二人並肩遠眺星盤清輝。"], ["mulan", "兄弟，從前我總以為必須扮作男兒身，方能護住家人。如今我才明白，作我自己便能護住這座城。"], ["p", "你是世間獨一無二的花木蘭。來，乾了這碗！"]], "eff": {"aff": ["me", 10], "affAll": 2}}], "duty": {"van": "先鋒交予花木蘭！千里奔襲，定教敵軍措手不及！", "guard": "城防交我坐鎮，一隻霧怪也休想攀上城垛！", "strat": "我雖不擅玄虛奇謀，但論夜戰地形與突襲路線，願替兄弟分憂！"}, "cold": "好幾旬未曾來校場比劃對飲，兄弟莫非忘了我這老袍澤？", "colds": ["好幾旬未曾來校場比劃對飲，兄弟莫非忘了我這老袍澤？", "戰馬都快閒出肥膘了，快出來與我跑上兩圈！"]}, "change": {"n": ["夫君來了？清光正好灑在軟榻上，快來飲一盞桂花清露。", "外頭霧寒露重，快進屋暖暖身子，妾身替你拂去肩頭霜氣。", "玉兔早已睡下，今夜這方小院唯留你我二人。", "聽見你的足音，連庭中桂樹的香氣都濃了幾分。"], "talk": ["當年吞下西王母靈藥、離地飛升那一瞬，我曾回望人間，卻再也落不回去了。", "后羿曾是頂天立地的英雄，可數千年過去，那段前緣早已如月下霜雪般消融。", "夫君從未將我當作高不可攀的月神供奉，而是視我為會冷、會寂寞的妻子，這教我心安。", "只要歸墟星盤長明，妾身便不上天亦不遠遁，只守在你身旁。", "莫怕我如前世般飛走——沒有你的地方，再美的瓊樓玉宇亦是牢籠。", "今夜月色極柔，像極了夫君凝望妾身時的眼神。"], "ev": [{"k": "v0", "at": 1, "t": "月下告別", "l": [["n", "中秋月滿，嫦娥獨自立於觀星臺上仰望明月，微涼指尖輕輕摩挲著一枚殘破的古石箭簇。"], ["p", "（緩步上前替她披上素裘）「在想后羿麼？"], ["change", "（微微一怔，旋即轉眸溫柔一笑，將箭簇輕輕投入星盤淨火化作點點流光）「方才確是想起他拉弓射日時的模樣……數千年執念，今夜總算能好好道一聲別了。"], ["p", "心裡若尚存遺憾，不必勉強自己放下。"], ["change", "（主動投入你懷中，輕輕環住你的腰身）「再無遺憾了。前世月華屬於廣寒，今生的我，唯屬於夫君。"]], "eff": {"pol": -8, "aff": ["me", 12]}}, {"k": "v1", "at": 3, "t": "桂露淨霧", "l": [["n", "嫦娥以月宮秘法釀成百壇桂花淨露分發全城，近郊黑霧應聲退散"]], "eff": {"pol": -10, "pop": 15, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "玉兔獻藥", "l": [["n", "嫦娥與華佗合製月華安神散，兵營傷卒迅速康復"]], "eff": {"sol": 25, "aff": ["me", 8]}}], "duty": {"feed": "妾身以清靜寬和之心打理內宅，願後宮如月夜般安寧。", "war": "妾身不善殺伐，但以月華護持軍陣、淨化瘴氣，定竭盡全力。", "rite": "引太陰清輝共鳴星盤，乃妾身本分所長。"}, "cold": "夫君久未踏足小院，廣寒的寒意似又爬上窗欞了……", "colds": ["夫君久未踏足小院，廣寒的寒意似又爬上窗欞了……", "桂花露溫了又涼，夫君今夜可還記得來賞月麼？"]}, "xiaoqiao": {"n": ["夫君來了？快坐，我剛溫好一壺江南碧螺春等著你呢。", "今夜月色這樣好，夫君不許再看公文了，陪小喬對弈一局可好？", "聽見你的足音我便把茶點端上來了，快趁熱嚐嚐。", "夫君的手好涼，快放進我掌心裡暖暖。"], "talk": ["周郎當年少年英發、卻早早離世，留我一人在江東守了許多寒暑。來到這歸墟，許是老天憐我太孤單罷。", "夫君從不逼我抹去過往，反而溫柔地等我自己走出來——這份體貼，教我徹底動了心。", "倘若他日在赤壁舊夢裡再見周郎，我會笑著告訴他，我如今過得極好。", "能替夫君打理市集、看城中百姓安居，小喬心裡歡喜得很。", "莫看我素日溫軟，夫君若總往別的殿裡走，我也會吃醋鬧些小性子的。", "今生有夫君相伴，小喬再也不怕長夜孤冷了。"], "ev": [{"k": "v0", "at": 1, "t": "夢醒柴桑", "l": [["n", "微雨夜裡，小喬從夢中輕輕驚醒，眼角猶掛著一滴未乾的淚珠。你連忙將她擁入懷中輕拍安撫。"], ["xiaoqiao", "（聲音微啞，靠在你胸口輕聲道）「我方才夢見赤壁江風、夢見周郎立在艨艟船頭回眸對我笑……他朝我揮了揮手，轉身步入霧中了。"], ["p", "（溫柔拭去她的淚痕）「他在祝願你安穩走完這一生。"], ["xiaoqiao", "（抬起水潤雙眸望著你，綻開釋然淺笑）「嗯，夢醒了，前世江風已散。夫君抱緊我，今生我只想守在你身邊。"]], "eff": {"aff": ["me", 12], "affAll": 2}}, {"k": "v1", "at": 3, "t": "江東絲市", "l": [["n", "小喬憑江東望族的商貿眼光，替城中引進一批緊俏絲絹換回大批軍糧"]], "eff": {"food": 40, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "誤曲逗君", "l": [["n", "小喬撫琴時故意撥錯一音，眼波流轉問你「夫君可聽出來了？」，二人相視而笑度過溫馨一夜"]], "eff": {"aff": ["me", 10]}}], "duty": {"feed": "交予小喬吧，定將後宮打理得溫馨和睦、井井有條。", "war": "妾身雖不擅領兵，然籌措軍糧、鼓舞士氣絕不落人後。", "rite": "願以江南清雅禮樂敬告星盤。"}, "cold": "夫君好幾旬未曾來喝小喬沏的茶了……莫非嫌我太愛黏人麼？", "colds": ["夫君好幾旬未曾來喝小喬沏的茶了……莫非嫌我太愛黏人麼？", "桂花糕都涼透了，夫君再不來，我可真要生氣不理你了。"]}, "zhenmi": {"n": ["夫君來了？請坐，這盞清茶剛沏好，最解案牘勞形。", "夜深霧重，夫君還記得踏進妾身院門，倒沒教我白等。", "剛核完這旬的庫房帳冊。夫君既至，今夜便只談風月，不談公事。", "這盞琉璃燈照得夫君眉眼柔和許多……過來坐近些吧。"], "talk": ["當年曹子桓初見我時也曾情深義重，可一旦登臨帝位、偏聽讒言，賜死我時連最後一面都未肯相見。", "是以初入此城時，我心裡築了一道高牆，絕不輕易對君王動情……未料還是被夫君一點點敲開了。", "《洛神賦》寫得再美，亦不過旁人遐想；唯有夫君握住我微涼的手替我暖熱時，我才覺自己是活生生的人。", "我雖會吃醋、會計較，卻絕不屑如昔年郭氏般使陰毒手段害人。我只要夫君心裡明鏡似的。", "這座城池的興盛有君一半、亦有我一半。夫妻同心，定能走得比大魏更遠。", "這一世，我不再是洛水邊孤魂幽影，而是夫君明媒正娶的妻子。"], "ev": [{"k": "v0", "at": 1, "t": "洛水遺恨", "l": [["n", "微寒河畔，甄宓靜靜凝視著倒映星盤清輝的水面，指尖緊緊攥著一卷寫著《塘上行》的舊絹。"], ["p", "（走到她身旁，輕輕攬住她單薄的肩）「還在怕重演鄴城的那場舊夢麼？"], ["zhenmi", "（回眸望你，眼底一閃而過的脆弱旋即化作堅定）「昔日曹丕賜我一死，教我恨了千年……可方才望著水面，我竟想不起他的面容了，滿心滿眼全是夫君替我披衣的模樣。"], ["p", "前塵便讓它隨流水東去。這輩子，我絕不負你。"], ["zhenmi", "（展露傾城清笑，主動輕輕靠上你的肩頭）「嗯。洛水舊恨已了，往後餘生，請夫君多多指教。"]], "eff": {"aff": ["me", 12], "talent": 1}}, {"k": "v1", "at": 3, "t": "開倉濟民", "l": [["n", "甄宓見城外流民挨餓，主動精算庫存並開倉施粥，既省糧又贏得滿城民心"]], "eff": {"pop": 25, "aff": ["me", 8]}}, {"k": "v2", "at": 6, "t": "精算內庫", "l": [["n", "甄宓替你查出庫房採買漏洞，當場追回大批糧財"]], "eff": {"food": 35, "aff": ["me", 8]}}], "duty": {"feed": "內宅用度與禮法交由妾身，定當精明公允、滴水不漏。", "war": "妾身可替夫君核對軍糧輜重與後勤調度，保前線無虞。", "rite": "以洛神清韻敬告星盤，願護此城長明。"}, "cold": "莫以豪賢故，棄捐素所愛……夫君這幾旬可是忘了妾身殿閣的門朝哪兒開？", "colds": ["莫以豪賢故，棄捐素所愛……夫君這幾旬可是忘了妾身殿閣的門朝哪兒開？", "茶涼了三回也不見人影，今夜夫君可得好好向妾身賠罪。"]}});
A("harem",{"wuzetian": {"visit": ["剛從哪位小丫頭房裡出來？身上這股俗氣脂粉味，快去洗乾淨再進本宮的門！"], "crown": "這方鳳印落在本宮手裡，才是真正的實至名歸！往後後宮上下，唯本宮之命是從！", "otherMain": "區區一塊鳳印而已。這朝堂與後宮真正說了算的是誰，大家心知肚明。", "calm": ["住口！在女皇面前喧嘩成何體統？各罰禁足半月、扣發月例，再鬧者直接打入冷牢！", "收起爾等那些粗陋把戲，本宮當年在太極宮所歷殺局比此狠絕十倍！"], "preg": "夫君，本宮有喜了。你我二人血脈所出之子，將來必是君臨天下的絕世奇才！", "birth": "快看這孩子天生貴氣逼人，果真不負你我之望！", "kidWen": "帝王心術與治國方略皆須精通，絕不可做軟弱庸主。", "kidWu": "強健筋骨方能震懾群雄，好孩子！"}, "change": {"visit": ["夫君多陪陪其餘姐妹乃分內之事，妾身在月下靜候便是。"], "crown": "承蒙夫君託付鳳印，妾身願以清輝平息後宮一切紛爭。", "otherMain": null, "calm": ["何苦為塵世瑣事動氣？飲盞桂花清露，心靜自然涼。"], "preg": "夫君……千年孤寂之後，妾身竟能為君孕育人間血脈，實乃天賜奇緣。", "birth": "瞧他（她）的眉眼，比滿天星辰還要澄澈明亮。", "kidWen": "字句清雅，甚具靈氣。", "kidWu": "強身護民，切莫忘卻仁心。"}, "xiaoqiao": {"visit": ["夫君剛從別殿回來呀？那今晚罰你多留一會兒，陪我說些體己話！"], "crown": "多謝夫君信重，小喬定以寬厚之心令後宮春風滿園。", "otherMain": null, "calm": ["姐妹們別動氣了，坐下來嚐塊桂花糕消消火吧。"], "preg": "夫君！小喬有喜了……咱們終於有了屬於自己的骨肉！", "birth": "他（她）的小手好軟好暖……夫君，謝謝你給我這般圓滿的家。", "kidWen": "讀書明理，將來作個儒雅君子（才女）。", "kidWu": "習武莫傷著自己，娘親會心疼的。"}, "zhenmi": {"visit": ["夫君剛從別殿回來麼？衣襟上沾著別家的香粉氣，先去更衣再進門！"], "crown": "鳳印既歸妾身，往後後宮帳目清晰、賞罰分明，絕不容許任何陰私讒言。", "otherMain": null, "calm": ["為些微末小事鬧到夫君面前何其失體？按章程各退一步，我替各位重核下月份例便是。"], "preg": "夫君……妾身有喜了。這一回，我定要親眼看著咱們的孩兒平安長大，再無宮廷陰霾。", "birth": "這孩子眉眼清秀靈動，真像極了夫君。", "kidWen": "字跡工整、文采斐然，不愧是娘親的好孩子。", "kidWu": "文武兼修方能自保，練武切莫傷著自己。"}});A("hstat",{"wuzetian": {"visitJail": "關得住本宮的人，關不住這天下大勢。", "exec": "哈哈哈哈！能親手殺了千古女皇，天運者，你也算名留青史了！"}, "change": {"visitJail": "牢籠再冷，也冷不過廣寒千年。", "exec": "塵緣既盡，重歸太陰便是。"}, "xiaoqiao": {"visitJail": "夫君，小喬是被冤枉的，牢裡好黑，快放我出去嘛……", "exec": "沒想到這一世，終究還是落得這般結局……"}, "zhenmi": {"visitJail": "又是這般未審先囚……夫君，你難道也要變成第二個曹丕麼？", "exec": "……終究還是逃不過這道賜死之命嗎。可悲，可嘆。"}});G.fac26=G.fac26||{};G.fac26.mem=Object.assign(G.fac26.mem||{},{"qinshihuang": ["wenchen", "以法度、郡縣與度量衡統一天下，視制度與中央集權為最高準則。"], "liubang": ["wenchen", "擅長統御蕭何、張良、韓信等開國群英，最懂收攏人心與政治平衡。"], "hanwudi": ["wuxun", "一生窮兵黷武、掃蕩匈奴、鑿空西域，唯崇鐵血開疆與大漢霸業。"], "caocao": ["wuxun", "亂世梟雄、唯才是舉，既通軍事又精權謀，始終以實力與兵權為王道。"], "tangtaizong": ["wuxun", "十八歲起兵太原、玄甲軍橫掃天下，兼具千古明君氣度與絕世騎兵統帥之能。"], "wuzetian": ["waiqi", "從才人、皇后一路登基稱帝的千古唯一女皇，天生以絕對權謀與內廷威壓統御天下。"], "zhaokuangyin": ["wenchen", "雖為武將出身，卻深知五代武夫亂政之禍，主張以文治穩固江山、重文抑武。"], "zhuyuanzhang": ["qingliu", "布衣乞丐出身，對貪官汙吏與奸商恨之入骨，一生以鐵腕保民、屯田築城為最高信念。"], "mulan": ["wuxun", "十二年血戰沙場、以軍功拒封尚書郎，天生屬於前線將士。"], "change": ["qingliu", "居廣寒數千年，看淡人間權勢爭鬥，唯願以月華淨化歸墟濁氣。"], "xiaoqiao": ["shanggu", "出身江東喬氏望族，擅長經營雅集、絲綢商貿與凝聚人心。"], "zhenmi": ["wenchen", "才情絕世、通曉治家與經史大義，看透宮廷險惡後極重法度與自我保護。"]});
S2("offL",{"mulan": "昔年我辭了尚書郎，今日為兄弟這座城，這方官印我接下了！", "change": "既承重託，妾身便以月華清心履職。", "xiaoqiao": "小喬領旨！定當細心盡責，替主公將財源與人心皆聚攏起來。", "zhenmi": "謝主公信重。甄宓定當精明履職、秉公無私，絕不負此官印。"});
